-- =====================================================================
-- FSTest food safety & hygiene products (from the Tay Scientific FSTest brochure): 8 products.
-- Run once in Supabase → SQL Editor. Safe to run again: it updates existing rows by SKU.
-- Needs the "features" column (added by import_lachoi_catalog.sql; added here too if missing).
-- Photos are in /public/products/fstest/ and the brand logo is /public/brands/fstest.png.
-- =====================================================================
alter table products add column if not exists features jsonb not null default '[]'::jsonb;

insert into brands (name, slug) values ('FSTest', 'fstest') on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values
  ('Equipment', 'equipment', 5), ('Life Science', 'life-science', 4), ('Consumables', 'consumables', 8)
on conflict (slug) do nothing;

-- Hide the old placeholders that these products replace
update products set is_active = false where sku like 'FST-LIF-%';  -- old name-only placeholders (no photo, no details)

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('MC31.3165.5', 'FSTest MC200 ATP Hygiene Monitor', 'fstest-mc200-atp-hygiene-monitor', 'Handheld ATP hygiene monitor that measures surface cleanliness in 10 seconds. It uses firefly luciferase bioluminescence: ATP from microorganisms or organic residue on a swab produces light, read as Relative Light Units (RLU). The higher the RLU, the greater the contamination. Ideal for HACCP verification in catering, food processing, healthcare and hotels.', '[["SKU", "MC31.3165.5"], ["Initializing time", "15 s or 30 s"], ["Testing time", "10 s"], ["Detection range", "0 ~ 999,999 RLU"], ["Precision", "1 × 10⁻¹⁶ mol ATP"], ["Detection error", "±5% or ±5 RLU"], ["Screen", "3.5 inch"], ["Storage", "> 20,000 results"], ["Battery", "5,200 mAh Li-ion, rechargeable"], ["Power supply", "5V/2A, USB Type-C"], ["Weight", "350 g"], ["Dimensions", "19.4 × 9.7 × 3.3 cm (L × W × H)"], ["Packing size", "1 unit"]]', '["Pass/fail RLU result in 10 seconds", "Double operation modes: capacitive touch screen or keypad", "Smart calibration: automatic light source and temperature calibration", "Stores more than 20,000 results", "Portable: 350 g with a 16-hour rechargeable battery", "Use with FSTest ATP Swab-QuickTest (MC32.3120.5)"]', 'equipment', '/products/fstest/mc200-atp-monitor.jpg'),
  ('MC32.3120.5', 'FSTest ATP Swab-QuickTest', 'fstest-atp-swab-quicktest', 'Instant surface cleanliness check. Quickly identify hidden organic residues and microbial contamination through ATP testing with the FSTest MC200 ATP Hygiene Monitor.', '[["SKU", "MC32.3120.5"], ["For use with", "FSTest MC200 ATP Hygiene Monitor (MC31.3165.5)"], ["Result time", "10 s"], ["Packing size", "10 swabs/pack"]]', '["Step 1: Swab a 10 × 10 cm surface in a Z pattern and return the swab to the tube", "Step 2: Break the blue valve and squeeze to release the liquid reagent", "Step 3: Shake gently 2–3 times (read within 30 seconds)", "Step 4: Insert into the MC200 monitor for a pass/fail RLU result in 10 seconds"]', 'consumables', '/products/fstest/atp-swab-quicktest.jpg'),
  ('MC32.3121.5', 'FSTest InstaPro Swab (Protein Residue)', 'fstest-instapro-swab-protein-residue', 'Ready-to-use swab for detecting protein residues on surfaces after cleaning. When protein is present the swab changes colour from green to grey to purple; higher protein levels give a faster, deeper colour change. Valuable for HACCP programs and hygiene monitoring. Also responds to some reducing substances such as simple sugars, tannins and ascorbic acid.', '[["SKU", "MC32.3121.5"], ["Detection", "Protein residue (Biuret reaction)"], ["Result time", "Up to 10 min"], ["Colour change", "Green → grey → purple"], ["Packing size", "25 swabs/pack"]]', '["Fast: clear colour change within 10 minutes", "High sensitivity: 80 µg in 1 minute, 50 µg in 5 minutes, 20 µg in 10 minutes (21–25°C)", "At 40°C detects 10 µg of protein in just 1 minute", "No instrument needed: swab, snap and shake", "Easy-to-read colour scale: green = pass, grey = caution, purple = fail"]', 'consumables', '/products/fstest/instapro-swab.jpg'),
  ('MC32.4129.5', 'FSTest Salmonella Rapid Test Kit', 'fstest-salmonella-rapid-test-kit', 'Salmonella colloidal gold rapid test kit. Colloidal gold rapid test for real-time risk screening of raw food, water, pet food and industrial process points. A lateral flow immunochromatographic assay gives an on-site qualitative result without micro-pipettes, thermal cyclers or an expert laboratory.', '[["SKU", "MC32.4129.5"], ["Target", "Salmonella"], ["Method", "Colloidal gold lateral flow (immunochromatography)"], ["Result", "Qualitative (T-line / C-line)"], ["Enrichment (incubation) time", "18–24 hr"], ["Analysis time", "10–15 min"], ["Packing size", "10 tests/kit"]]', '["Fast: the whole test takes only 10–20 minutes, excluding enrichment time", "Intuitive results: read by the appearance of lines in the T-zone, with an internal control line", "Stable performance with high sensitivity", "No auxiliary equipment needed, saving cost and bench space", "Suitable for a wide range of food and water samples", "Backed by over 20 years of research and development"]', 'life-science', '/products/fstest/salmonella-rapid-test.jpg'),
  ('MC32.4116.5', 'FSTest E. coli O157 Rapid Test Kit', 'fstest-e-coli-o157-rapid-test-kit', 'E. coli O157 colloidal gold rapid test kit. Colloidal gold rapid test for real-time risk screening of raw food, water, pet food and industrial process points. A lateral flow immunochromatographic assay gives an on-site qualitative result without micro-pipettes, thermal cyclers or an expert laboratory.', '[["SKU", "MC32.4116.5"], ["Target", "E. coli O157"], ["Method", "Colloidal gold lateral flow (immunochromatography)"], ["Result", "Qualitative (T-line / C-line)"], ["Enrichment (incubation) time", "18–24 hr"], ["Analysis time", "10–15 min"], ["Packing size", "10 tests/kit"]]', '["Fast: the whole test takes only 10–20 minutes, excluding enrichment time", "Intuitive results: read by the appearance of lines in the T-zone, with an internal control line", "Stable performance with high sensitivity", "No auxiliary equipment needed, saving cost and bench space", "Suitable for a wide range of food and water samples", "Backed by over 20 years of research and development"]', 'life-science', '/products/fstest/ecoli-o157-rapid-test.jpg'),
  ('MC32.4115.5', 'FSTest Listeria monocytogenes Rapid Test Kit', 'fstest-listeria-monocytogenes-rapid-test-kit', 'Listeria monocytogenes colloidal gold rapid test kit. Colloidal gold rapid test for real-time risk screening of raw food, water, pet food and industrial process points. A lateral flow immunochromatographic assay gives an on-site qualitative result without micro-pipettes, thermal cyclers or an expert laboratory.', '[["SKU", "MC32.4115.5"], ["Target", "Listeria monocytogenes"], ["Method", "Colloidal gold lateral flow (immunochromatography)"], ["Result", "Qualitative (T-line / C-line)"], ["Enrichment (incubation) time", "24 hr"], ["Analysis time", "10–15 min"], ["Packing size", "10 tests/kit"]]', '["Fast: the whole test takes only 10–20 minutes, excluding enrichment time", "Intuitive results: read by the appearance of lines in the T-zone, with an internal control line", "Stable performance with high sensitivity", "No auxiliary equipment needed, saving cost and bench space", "Suitable for a wide range of food and water samples", "Backed by over 20 years of research and development"]', 'life-science', '/products/fstest/listeria-rapid-test.png'),
  ('MC32.4114.5', 'FSTest Staphylococcus aureus Rapid Test Kit', 'fstest-staphylococcus-aureus-rapid-test-kit', 'Staphylococcus aureus colloidal gold rapid test kit. Colloidal gold rapid test for real-time risk screening of raw food, water, pet food and industrial process points. A lateral flow immunochromatographic assay gives an on-site qualitative result without micro-pipettes, thermal cyclers or an expert laboratory.', '[["SKU", "MC32.4114.5"], ["Target", "Staphylococcus aureus"], ["Method", "Colloidal gold lateral flow (immunochromatography)"], ["Result", "Qualitative (T-line / C-line)"], ["Enrichment (incubation) time", "24 hr"], ["Analysis time", "10–15 min"], ["Packing size", "10 tests/kit"]]', '["Fast: the whole test takes only 10–20 minutes, excluding enrichment time", "Intuitive results: read by the appearance of lines in the T-zone, with an internal control line", "Stable performance with high sensitivity", "No auxiliary equipment needed, saving cost and bench space", "Suitable for a wide range of food and water samples", "Backed by over 20 years of research and development"]', 'life-science', '/products/fstest/staph-aureus-rapid-test.png'),
  ('FST-COUNT-PLATE', 'FSTest Rapid Microbial Count Plates', 'fstest-rapid-microbial-count-plates', 'Ready-to-use, dry rehydratable culture media plates with pre-formulated nutrients, a cold-water-soluble gelling agent and built-in chromogenic indicators. They replace agar cooking, autoclave sterilization and petri dish pouring with a simple inoculate, incubate, count workflow.', '[["Format", "Dry rehydratable film plate with chromogenic indicator"], ["Types", "Aerobic count, coliform and more"]]', '["90% less space than agar pour plates: more room in the incubator", "About 65% lower cost: no media preparation, labour or heavy cleaning", "50% less time: inoculate, incubate, count", "Available for aerobic count, coliform and other organisms (ask us for the full range)"]', 'life-science', '/products/fstest/count-plate.jpg')
) as v(sku, name, slug, description, specs, features, cat, image_url)
join categories c on c.slug = v.cat
cross join (select id from brands where slug = 'fstest') b
on conflict (sku) do update set
  name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id,
  image_url = excluded.image_url, is_active = true;

-- Check: should return 8
select count(*) as fstest_products from products p join brands b on b.id = p.brand_id
where b.slug = 'fstest' and p.is_active and p.sku not like 'FST-LIF-%';
